    prisma.deals.aggregate({
      where: { userId, dealType: { in: ['emails', 'contacts', 'sales'] } },
      _sum: { value: true },
    }),
  ])

  const [deals, totalSum] = await Promise.all([
    query,
    prisma.deals.count({ where: { userId, dealType } }),
  ])

  return NextResponse.json({
    deals,
    total: totalSum,
    totalLeads: total[0]?._sum.value ?? 0,
  })
}

