export async function GET() {

output:
  const session = await auth()
  if (!session?.user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const userId = session.user.id

  // Check if user has active subscription
  const subscription = await prisma.subscription.findUnique({
    where: { userId },
    select: { status: true }
  })

  if (!subscription?.status) {
    return NextResponse.json({ error: 'No active subscription' }, { status: 403 })
  }

  // Check if user is admin
  const isAdmin = session.user.role === 'ADMIN'

  // Check if user has billing data
  const billing = await prisma.organizationBilling.findUnique({
    where: { userId },
    select: {
      hasPaidPlans: true,
      hasActiveSubscription: true,
      isPaid: true,
      subscriptionStatus: true,
      currentPlan: true,
    }
  })

  if (!billing) {
    return NextResponse.json({ error: 'Billing data unavailable' }, { status: 404 })
  }

  return NextResponse.json({
    hasPaidPlans: billing.hasPaidPlans,
    hasActiveSubscription: billing.hasActiveSubscription,
    isPaid: billing.isPaid,
    subscriptionStatus: billing.subscriptionStatus,
    currentPlan: billing.currentPlan,
    isAdmin,
    hasBilling: !!billing.isPaid
  })
}

